import re

def normalized_identity(value):
    return "".join(ch for ch in str(value).lower() if ch.isalnum())

def amount_text_to_cents(value):
    cleaned = str(value).replace(",", "")
    whole, dot, fraction = cleaned.partition(".")
    fraction = (fraction + "00")[:2] if dot else "00"
    return int(whole) * 100 + int(fraction)

def parse_share_lines(content):
    parsed = []
    ignored_labels = {"total", "subtotal", "grandtotal", "tax", "tip", "bill", "amount", "dinner", "workdinner"}
    for raw_line in re.split(r"[\n;]+", str(content)):
        line = raw_line.strip()
        if not line:
            continue
        amount_match = re.search(
            r"(?<!\d)(?:\$|USD\s*)?(\d[\d,]*(?:\.\d{1,2})?)\s*(?:USD|dollars?)?\s*$",
            line,
            flags=re.IGNORECASE,
        )
        if amount_match is None:
            continue
        label = line[:amount_match.start()].strip(" \t-*:=–—")
        label = re.sub(r"(?:'s)?\s+share\s*$", "", label, flags=re.IGNORECASE).strip()
        label = re.sub(r"\s+owes\s*$", "", label, flags=re.IGNORECASE).strip()
        cents = amount_text_to_cents(amount_match.group(1))
        if label and normalized_identity(label) not in ignored_labels and cents > 0:
            parsed.append({"label": label, "amount_cents": cents})
    return parsed

ranked_note_candidates = []
for note in dinner_note_details:
    parsed_shares = parse_share_lines(note["content"])
    searchable_text = (str(note["title"]) + " " + str(note["content"])).lower()
    date_match = str(note["created_at"]).startswith(yesterday_iso) or str(note["updated_at"]).startswith(yesterday_iso)
    relevance_score = (
        (10 if "dinner" in str(note["title"]).lower() else 0)
        + (4 if date_match else 0)
        + (2 if any(term in searchable_text for term in ("work", "coworker", "colleague", "share")) else 0)
        + len(parsed_shares)
    )
    ranked_note_candidates.append({"note": note, "parsed_shares": parsed_shares, "score": relevance_score})

usable_note_candidates = [candidate for candidate in ranked_note_candidates if candidate["parsed_shares"]]
if not usable_note_candidates:
    raise ValueError("No dinner note with parseable positive individual shares was found")
usable_note_candidates.sort(
