```python
def numeric_amount_to_cents(value):
    return int(round(float(value) * 100))

paid_evidence = {}
pending_requests = []
for share in owed_shares:
    email_key = str(share["user_email"]).lower()
    matching_payments = [
        transaction for transaction in received_transactions
        if str(transaction["sender"]["email"]).lower() == email_key
        and numeric_amount_to_cents(transaction["amount"]) == share["amount_cents"]
    ]
    if matching_payments:
        paid_evidence[email_key] = [transaction["transaction_id"] for transaction in matching_payments]
    else:
        pending_requests.append({
            "user_email": share["user_email"],
            "amount": share["amount"],
            "amount_cents": share["amount_cents"],
            "description": "Work Dinner",
        })

planned_emails = [str(request["user_email"]).lower() for request in pending_requests]
if len(planned_emails) != len(set(planned_emails)):
    raise ValueError("Duplicate request recipients were derived")
