```python
import re

def normalized_identity(value):
    return "".join(ch for ch in str(value).lower() if ch.isalnum())

def amount_text_to_cents(value):
    cleaned = str(value).replace(",", "")
    whole, dot, fraction = cleaned.partition(".")
    fraction = (fraction + "00")[:2] if dot else "00"
    return int(whole) * 100 + int(fraction)

def parse_share_lines(content):
    parsed = []
    ignored_labels = {"total", "subtotal", "grandtotal", "tax", "tip", "bill", "amount", "dinner", "workdinner"}
    for raw_line in re.split(r"[\n;]+", str(content)):
        line = raw_line.strip()
        if not line:
            continue
        amount_match = re.search(
            r"(?<!\d)(?:\$|USD\s*)?(\d[\d,]*(?:\.\d{1,2})?)\s*(?:USD|dollars?)?\s*$",
            line,
            flags=re.IGNORECASE,
        )
        if amount_match is None:
            continue
        label = line[:amount_match.start()].strip(" \t-*:=–—")
        label = re.sub(r"(?:'s)?\s+share\s*$", "", label, flags=re.IGNORECASE).strip()
        label = re.sub(r"\s+owes\s*$", "", label, flags=re.IGNORECASE).strip()
        cents = amount_text_to_cents(amount_match.group(1))
        if label and normalized_identity(label) not in ignored_labels and cents > 0:
            parsed.append({"label": label, "amount_cents": cents})
    return parsed

ranked_note_candidates = []
for note in dinner_note_details:
    parsed_shares = parse_share_lines(note["content"])
    searchable_text = (str(note["title"]) + " " + str(note["content"])).lower()
    date_match = str(note["created_at"]).startswith(yesterday_iso) or str(note["updated_at"]).startswith(yesterday_iso)
    relevance_score = (
        (10 if "dinner" in str(note["title"]).lower() else 0)
        + (4 if date_match else 0)
        + (2 if any(term in searchable_text for term in ("work", "coworker", "colleague", "share")) else 0)
        + len(parsed_shares)
    )
    ranked_note_candidates.append({"note": note, "parsed_shares": parsed_shares, "score": relevance_score})

usable_note_candidates = [candidate for candidate in ranked_note_candidates if candidate["parsed_shares"]]
if not usable_note_candidates:
    raise ValueError("No dinner note with parseable positive individual shares was found")
usable_note_candidates.sort(
    key=lambda candidate: (
        candidate["score"],
        len(candidate["parsed_shares"]),
        str(candidate["note"]["updated_at"]),
    ),
    reverse=True,
)
best_rank = (usable_note_candidates[0]["score"], len(usable_note_candidates[0]["parsed_shares"]))
top_candidates = [
    candidate for candidate in usable_note_candidates
    if (candidate["score"], len(candidate["parsed_shares"])) == best_rank
]
if len(top_candidates) != 1:
    raise ValueError("Dinner-share note selection is ambiguous")
selected_dinner_note = top_candidates[0]

self_aliases = {
    normalized_identity(supervisor_profile["first_name"]),
    normalized_identity(supervisor_profile["last_name"]),
    normalized_identity(supervisor_profile["first_name"] + supervisor_profile["last_name"]),
    str(supervisor_profile["email"]).lower(),
}

owed_shares = []
unmatched_share_labels = []
seen_owed_emails = set()
for parsed_share in selected_dinner_note["parsed_shares"]:
    label = parsed_share["label"]
    label_normalized = normalized_identity(label)
    if label_normalized in self_aliases or str(label).lower() in self_aliases:
        continue
    exact_matches = []
    for contact in coworker_contacts:
        aliases = {
            normalized_identity(contact["first_name"]),
            normalized_identity(contact["last_name"]),
            normalized_identity(contact["first_name"] + contact["last_name"]),
            str(contact["email"]).lower(),
        }
        if label_normalized in aliases or str(label).lower() in aliases:
            exact_matches.append(contact)
    matches = exact_matches
    if not matches:
        matches = [
            contact for contact in coworker_contacts
            if label_normalized and any(
                alias and (alias in label_normalized or label_normalized in alias)
                for alias in (
                    normalized_identity(contact["first_name"]),
                    normalized_identity(contact["first_name"] + contact["last_name"]),
                )
            )
        ]
    unique_matches = {str(contact["email"]).lower(): contact for contact in matches}
    if len(unique_matches) != 1:
        unmatched_share_labels.append({"label": label, "candidate_emails": sorted(unique_matches)})
        continue
    email_key, contact = next(iter(unique_matches.items()))
    if email_key in seen_owed_emails:
        raise ValueError("A coworker appears more than once in the selected share note")
    seen_owed_emails.add(email_key)
    owed_shares.append({
        "label": label,
        "contact_name": (contact["first_name"] + " " + contact["last_name"]).strip(),
        "user_email": contact["email"],
        "amount_cents": parsed_share["amount_cents"],
        "amount": parsed_share["amount_cents"] / 100,
    })

if unmatched_share_labels:
    raise ValueError("Some share labels did not map uniquely to coworker contacts: " + repr(unmatched_share_labels))
if not owed_shares:
    raise ValueError("No coworker shares remained after excluding the supervisor")

print({
    "selected_note": {
        "note_id": selected_dinner_note["note"]["note_id"],
        "title": selected_dinner_note["note"]["title"],
    },
    "mapped_owed_shares": owed_shares,
})
